import { User } from "../models/user";
import { Session } from "./session";

interface PermissionRule {
  resource: string;
  action: string;
}

const RULES: PermissionRule[] = [
  { resource: "posts", action: "read" },
  { resource: "posts", action: "write" },
];

export function checkAccess(session: Session, resource: string, action: string): boolean {
  if (isSessionExpired(session)) return false;
  if (session.user.role === "admin") return true;
  return RULES.some((r) => r.resource === resource && r.action === action);
}

function isSessionExpired(s: Session): boolean {
  return Date.now() > s.expiresAt;
}
